mapper.select:
SELECT v."動画ID" AS "videoId", v."動画ファイル名" AS "fileName", v."撮影開始日時" AS "startedAt", v."撮影終了日時" AS "endedAt", v."動画時間秒" AS "durationSeconds", v."取込状態コード" AS "importState", COALESCE(counts."snapshotCount", 0) AS "snapshotCount", COALESCE(counts."completedCount", 0) AS "completedCount" FROM public."MON_学習モニター動画情報" v LEFT JOIN LATERAL ( SELECT COUNT(*) AS "snapshotCount", COUNT(*) FILTER (WHERE a."分析状態コード" = 'COMPLETED') AS "completedCount" FROM public."MON_学習モニタースナップショット情報" s LEFT JOIN public."MON_学習モニター画像分析情報" a ON a."スナップショットID" = s."スナップショットID" AND a."最新版フラグ" = '1' WHERE s."動画ID" = v."動画ID" AND s."状態" = '1' AND s."切出状態コード" = 'CREATED' ) counts ON TRUE WHERE v."状態" = '1' AND v."撮影終了日時" >= #{from} AND v."撮影開始日時" <= #{to}
AND v."動画ID" = #{videoId}
ORDER BY v."撮影開始日時"

SELECT s."スナップショットID" AS "snapshotId", s."動画ID" AS "videoId", v."動画ファイル名" AS "videoFileName", s."撮影日時" AS "capturedAt", s."保存パス" AS "imagePath", s."幅" AS "width", s."高さ" AS "height", COALESCE(a."分析状態コード", 'WAITING') AS "analysisState", CASE WHEN a."手動修正フラグ" = '1' THEN a."手動修正結果コード" ELSE a."最終分析結果コード" END AS "resultCode", COALESCE(a."最終信頼度", a."一次信頼度") AS "confidence", CASE WHEN a."手動修正フラグ" = '1' THEN a."手動修正理由" ELSE a."最終判定理由" END AS "reason", (a."手動修正フラグ" = '1') AS "manual", COALESCE(a."バージョン", 1) AS "version" FROM public."MON_学習モニタースナップショット情報" s JOIN public."MON_学習モニター動画情報" v ON v."動画ID" = s."動画ID" LEFT JOIN public."MON_学習モニター画像分析情報" a ON a."スナップショットID" = s."スナップショットID" AND a."最新版フラグ" = '1' WHERE s."状態" = '1' AND s."切出状態コード" = 'CREATED' AND s."撮影日時" >= #{from} AND s."撮影日時" <= #{to}
AND s."動画ID" = #{videoId}
AND a."分析状態コード" = 'COMPLETED'
AND COALESCE(a."分析状態コード", 'WAITING') IN ('WAITING', 'RUNNING')
AND a."分析状態コード" = 'ERROR'
AND CASE WHEN a."手動修正フラグ" = '1' THEN a."手動修正結果コード" ELSE a."最終分析結果コード" END = #{resultCode}
ORDER BY s."撮影日時", s."スナップショットID"
